var gl,noctaves,c;
function setup() {
  createCanvas(1024, 768,WEBGL);
	gl=this.canvas.getContext('webgl');
	gl.disable(gl.DEPTH_TEST);
	noctaves=1;
	initc();
	test=createShader(vert, frag);//shaders are loaded
  shader(test);//shaders are applied	
}
function draw() {    
	test.setUniform("iResolution", [width,height]);//pass some values to the shader
  test.setUniform("iTime", millis()*.001);
	test.setUniform('iMouse',[(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
	test.setUniform("noctaves",noctaves);
	test.setUniform("c",c);
	shader(test);
	box(width);
}
function mouseReleased(){
	noctaves=noctaves==6?1:noctaves+1;
	if(noctaves==1)initc();
}
function initc(){
	c=[];
	for(var i=0;i<22;i++){
		if(i<19)c[i]=random(-10,10);
		else c[i]=random(-1,1);
	}
}

// === Tab: shaders ===
var frag=`
// Author Pierre MARZIN 01/2017

#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 iResolution;
uniform vec2 iMouse;
uniform float iTime;
uniform int noctaves;
uniform float c[22];
float random (in vec2 _st) {
    return fract(sin(dot(_st.xy,
                         vec2(12.9898,78.233)))*
        43758.5453123);
}
float noise( in vec2 x )
{
	return sin(1.5*x.x)*sin(1.5*x.y);
}
vec3 smootherstep(vec3 edge0, vec3 edge1, vec3 v) {
  // Scale, and clamp x to 0..1 range
  float x = clamp((v.x - edge0.x) / (edge1.x - edge0.x), 0.0, 1.0);
	float y = clamp((v.y - edge0.y) / (edge1.y - edge0.y), 0.0, 1.0);
	float z = clamp((v.z - edge0.z) / (edge1.z - edge0.z), 0.0, 1.0);
  // Evaluate polynomial
  return vec3(x * x * x * (x * (x * 6.0 - 15.0) + 10.0),y * y * y * (y * (y * 6.0 - 15.0) + 10.0),z * z * z * (z * (z * 6.0 - 15.0) + 10.0));
}
mat2 rot = mat2( sin(c[18]),  cos(c[18]), cos(c[18]), -sin(c[18]) );
float fbm ( in vec2 _st) {
    float v = 0.0;
    float a = 0.5;
    vec2 shift = vec2(100.0);
    for (int i = 0; i < 10; ++i) {//noprotect
		if(i>=noctaves)break;
        v += a * noise(_st);
        _st = rot * _st * 2.0 + shift;
        a *= 0.5;
    }
    return v;
}
float fbmd(vec2 p){
	return fbm(p)-fbm(p+.01);
}
void main() {
vec2 mouse=iMouse/iResolution;
    vec2 st = 5.0*mouse.y*(gl_FragCoord.xy/iResolution.xy-.5);
		//st.x*=iResolution.x/iResolution.y;
    vec3 color = vec3(1.0);
    vec2 q = vec2(0.);
    q.x = fbm( c[0]*st + .1*c[1]*cos(0.2*iTime));
    q.y = fbm( c[2]*st + .1*c[3]*sin(1.0-0.15*iTime));
    vec2 r = vec2(0.);
		st+=.5+q;
    r.x = fbm(c[4]*st+c[5]*q+vec2(c[6],c[7]));
    r.y = fbm( c[8]*st+c[9]*q+vec2(c[11],c[12]));
    float f = abs(fbm(c[13]*st+c[14]*q+c[15]*r+vec2(c[16],c[17])));
		vec3 col1=vec3(.9,.8,.5);
		vec3 col2=vec3(.6,.7,.4);
		vec3 col3=vec3(.9,.8,.8);
		color=f>.5?mix(col1,col2,vec3(f)):mix(col2,col3,vec3(f));
		color*=vec3(.5*f*f*f,.8*f*f,.7*f);	
		color=1.0-color;
		color=pow(color, vec3(19.6));
    gl_FragColor = vec4(color,1.);
}

`
var vert=`
//standard vertex shader
#ifdef GL_ES
      precision highp float;
    #endif
		#extension GL_OES_standard_derivatives : enable
    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;
    attribute vec4 aVertexColor;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec4 var_vertCol;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;

    void main() {
      gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);

      // just passing things through
      var_vertPos      = aPosition;
      var_vertCol      = aVertexColor;
      var_vertNormal   = aNormal;
      var_vertTexCoord = aTexCoord;
    }
`;

